package ua.empirecraft.feudal;

import java.sql.SQLException;
import java.util.*;
import static ua.empirecraft.feudal.Database.*;
import static ua.empirecraft.feudal.Model.*;
import static ua.empirecraft.feudal.FeudalService.DAY;
import ua.empirecraft.feudal.FeudalService.Actor;

/** Estate-bound agreements. Every edit is a new immutable revision; active terms survive negotiation. */
public final class ContractService {
    final FeudalService s; final Database db; final PoliticsService politics;
    public Runnable changed=()->{};
    public java.util.function.Function<String,String> names=id->id;
    public java.util.function.Function<Estate,String> estateNames=Estate::name;
    public ContractService(FeudalService s,PoliticsService politics)throws SQLException{
        this.s=s;db=s.db;this.politics=politics;
        for(String ddl:List.of(
            "CREATE TABLE IF NOT EXISTS vc_contract(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,child VARCHAR(80),parent VARCHAR(80),revision INT,active_rev INT DEFAULT 0,status VARCHAR(20),starts BIGINT DEFAULT 0,ends BIGINT DEFAULT 0,next_due BIGINT DEFAULT 0,sub_due BIGINT DEFAULT 0,exit_at BIGINT DEFAULT 0,exit_party VARCHAR(80),exit_yes VARCHAR(80))",
            "CREATE TABLE IF NOT EXISTS vc_revision(contract BIGINT,rev INT,terms CLOB,created BIGINT,actor VARCHAR(80),child_name VARCHAR(100),parent_name VARCHAR(100),child_sign VARCHAR(80),parent_sign VARCHAR(80),signed_at BIGINT DEFAULT 0,PRIMARY KEY(contract,rev))",
            "CREATE TABLE IF NOT EXISTS vc_accept(contract BIGINT,rev INT,estate VARCHAR(80),ruler VARCHAR(36),fingerprint CLOB,phase VARCHAR(10),PRIMARY KEY(contract,rev,estate))",
            "CREATE TABLE IF NOT EXISTS vc_vote(contract BIGINT,rev INT,estate VARCHAR(80),voter VARCHAR(36),choice BOOLEAN,fingerprint CLOB,PRIMARY KEY(contract,rev,estate,voter))",
            "CREATE TABLE IF NOT EXISTS vc_obligation(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,contract BIGINT,rev INT,source VARCHAR(80),target VARCHAR(80),asset VARCHAR(80),amount BIGINT,paid BIGINT DEFAULT 0,due BIGINT,penalty BOOLEAN DEFAULT FALSE,late BOOLEAN DEFAULT FALSE)",
            "CREATE INDEX IF NOT EXISTS vc_debts ON vc_obligation(contract,due)",
            "CREATE TABLE IF NOT EXISTS vc_history(seq BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,contract BIGINT,at_time BIGINT,actor VARCHAR(80),event VARCHAR(32),detail CLOB)",
            "CREATE TABLE IF NOT EXISTS vc_goods(estate VARCHAR(80),material VARCHAR(80),quantity BIGINT,PRIMARY KEY(estate,material))",
            "CREATE TABLE IF NOT EXISTS vc_item(op VARCHAR(36) PRIMARY KEY,obligation BIGINT,estate VARCHAR(80),material VARCHAR(80),quantity BIGINT,withdrawal BOOLEAN)",
            "CREATE TABLE IF NOT EXISTS vc_permission(child VARCHAR(80),action VARCHAR(16),rev INT,PRIMARY KEY(child,action))"
        ))db.execute(ddl);
        db.execute("ALTER TABLE vc_revision ADD COLUMN IF NOT EXISTS child_sign_name VARCHAR(100)");
        db.execute("ALTER TABLE vc_revision ADD COLUMN IF NOT EXISTS parent_sign_name VARCHAR(100)");
        db.execute("ALTER TABLE vc_revision ADD COLUMN IF NOT EXISTS expires_at BIGINT DEFAULT 0");
        db.execute("ALTER TABLE vc_revision ADD COLUMN IF NOT EXISTS first_due BIGINT DEFAULT 0");
    }
    public Map<String,Object> get(long id)throws SQLException{var c=db.one("SELECT * FROM vc_contract WHERE id=?",id);require(c!=null,"Договір не знайдено.");return c;}
    public Map<String,Object> revision(long id,int rev)throws SQLException{var r=db.one("SELECT * FROM vc_revision WHERE contract=? AND rev=?",id,rev);require(r!=null,"Редакцію не знайдено.");return r;}
    public ContractTerms terms(long id,int rev)throws SQLException{return ContractTerms.decode(string(revision(id,rev),"terms"));}
    public int rev(Map<String,Object> c){return Math.toIntExact(number(c,"revision"));}
    public Map<String,Object> active(String child)throws SQLException{return db.one("SELECT * FROM vc_contract WHERE child=? AND active_rev>0 AND status IN('ACTIVE','NOTICE')",child);}
    void ruler(Actor a,String estate)throws SQLException{require(s.estate(estate).active() && Objects.equals(a.id(),s.estate(estate).lord()),"Дію особисто виконує чинний правитель володіння.");}
    String party(Actor a,Map<String,Object> c)throws SQLException{
        for(String side:List.of("child","parent")){String id=string(c,side);if(Objects.equals(a.id(),s.estate(id).lord())){ruler(a,id);return id;}}
        throw new IllegalArgumentException("Ви не правитель сторони договору.");
    }
    String fingerprint(String estate)throws SQLException{return politics==null?s.estate(estate).toString():politics.fingerprint(estate);}
    void event(long id,String actor,String event,String detail)throws SQLException{db.execute("INSERT INTO vc_history(contract,at_time,actor,event,detail) VALUES(?,?,?,?,?)",id,s.now(),actor,event,detail);}
    public List<Map<String,Object>> list()throws SQLException{return db.query("SELECT * FROM vc_contract ORDER BY id DESC");}
    public long create(Actor actor,String child,String parent){return db.transaction(()->{
        childCheck(actor,child,parent);require(db.one("SELECT id FROM vc_contract WHERE child=? AND status IN('DRAFT','ACTIVE','NOTICE')",child)==null,"Для васала вже є договір. Відкрийте його та створіть нову редакцію.");
        require(s.contract(child)==null,"Спершу завершіть попередній класичний договір за його правилами.");
        String old=s.parent(child);require(old==null || old.equals(parent),"Спершу погодьте звільнення від попереднього сюзерена.");
        db.execute("INSERT INTO vc_contract(child,parent,revision,status) VALUES(?,?,1,'DRAFT')",child,parent);
        long id=number(db.one("SELECT MAX(id) AS id FROM vc_contract"),"id");insertRevision(id,1,new ContractTerms(),actor.id());event(id,actor.id(),"CREATE",child+" → "+parent);return id;
    });}
    void childCheck(Actor a,String child,String parent)throws SQLException{
        require(Objects.equals(a.id(),s.estate(child).lord()) || Objects.equals(a.id(),s.estate(parent).lord()),"Проєкт створює правитель однієї зі сторін.");
        require(!Objects.equals(s.estate(child).lord(),s.estate(parent).lord()),"Потрібні два різні правителі для двостороннього підписання.");
        s.validateLink(s.estate(child),s.estate(parent));
    }
    int nextRev(long id)throws SQLException{return Math.toIntExact(number(db.one("SELECT MAX(rev) AS n FROM vc_revision WHERE contract=?",id),"n"))+1;}
    void insertRevision(long id,int rev,ContractTerms t,String actor)throws SQLException{db.execute("INSERT INTO vc_revision(contract,rev,terms,created,actor) VALUES(?,?,?,?,?)",id,rev,t.encode(),s.now(),actor);}
    void current(Map<String,Object> c,int expected){require(number(c,"active_rev")==0 || number(c,"ends")==0 || s.now()<number(c,"ends"),"Строк чинного договору вже завершено.");require(rev(c)==expected,"Редакція вже змінилася. Відкрийте договір знову.");require(Set.of("DRAFT","ACTIVE").contains(string(c,"status")),"Договір закрито або розпочато вихід.");}
    public int edit(Actor a,long id,int expected,String key,String value){return db.transaction(()->{
        var c=get(id);current(c,expected);party(a,c);var old=terms(id,expected);var editing=number(c,"active_rev")==expected?old.with("extend","0"):old;var next=editing.with(key,value);require(!next.encode().equals(old.encode()),"Значення не змінилося.");
        if(number(c,"active_rev")>0 && Set.of("days","extend").contains(key))require(terms(id,(int)number(c,"active_rev")).yes("renew"),"Чинна редакція не дозволяє продовження строку.");
        int rev=nextRev(id);insertRevision(id,rev,next,a.id());db.execute("UPDATE vc_contract SET revision=? WHERE id=?",rev,id);event(id,a.id(),"EDIT","Редакція "+rev+": "+key+" = "+value);return rev;
    });}
    public int amend(Actor a,long id,int expected){return db.transaction(()->{var c=get(id);current(c,expected);party(a,c);require(number(c,"active_rev")==expected,"Проєкт нової редакції вже існує.");int next=nextRev(id);insertRevision(id,next,terms(id,expected).with("extend","0"),a.id());db.execute("UPDATE vc_contract SET revision=? WHERE id=?",next,id);event(id,a.id(),"AMEND","Нова редакція "+next);return next;});}
    public void reject(Actor a,long id,int expected){db.transaction(()->{var c=get(id);current(c,expected);party(a,c);require(number(c,"active_rev")!=expected,"Чинний договір розривається лише за умовами виходу.");if(number(c,"active_rev")==0)db.execute("UPDATE vc_contract SET status='REJECTED' WHERE id=?",id);else db.execute("UPDATE vc_contract SET revision=active_rev WHERE id=?",id);event(id,a.id(),"REJECT","Редакція "+expected);return null;});}
    boolean council(String estate)throws SQLException{if(politics==null)return false;return Set.of(PoliticalModel.Government.REPUBLIC,PoliticalModel.Government.TRIBAL_COUNCIL).contains(politics.state(estate).government());}
    public void vote(Actor a,long id,int expected,String estate,boolean yes){db.transaction(()->{
        var c=get(id);current(c,expected);require(List.of(string(c,"child"),string(c,"parent")).contains(estate) && council(estate),"Рада цієї сторони не голосує за договір.");
        require(politics.electorate(estate).contains(a.id()),"Ви не належите до чинного складу виборців ради.");
        db.execute("MERGE INTO vc_vote KEY(contract,rev,estate,voter) VALUES(?,?,?,?,?,?)",id,expected,estate,a.id(),yes,fingerprint(estate));event(id,a.id(),"VOTE",estate+" "+yes+" редакція "+expected);return null;
    });}
    boolean mandate(long id,int rev,String estate)throws SQLException{
        if(!council(estate))return true;Set<String> electorate=politics.electorate(estate);long yes=0;
        for(var v:db.query("SELECT voter FROM vc_vote WHERE contract=? AND rev=? AND estate=? AND choice=TRUE AND fingerprint=?",id,rev,estate,fingerprint(estate)))if(electorate.contains(string(v,"voter")))yes++;
        return yes>electorate.size()/2;
    }
    void approved(Map<String,Object> c,int rev)throws SQLException{
        long id=number(c,"id");for(String side:List.of("child","parent")){
            String e=string(c,side);var r=db.one("SELECT * FROM vc_accept WHERE contract=? AND rev=? AND estate=?",id,rev,e);
            require(r!=null && Objects.equals(string(r,"ruler"),s.estate(e).lord()) && Objects.equals(string(r,"fingerprint"),fingerprint(e)),"Обидві сторони мають погодити чинну редакцію з актуальними повноваженнями.");
            require(mandate(id,rev,e),"Потрібна більшість голосів ради за цю редакцію договору.");
        }
    }
    public void agree(Actor a,long id,int expected){db.transaction(()->{
        var c=get(id);current(c,expected);require(number(c,"active_rev")!=expected,"Редакція вже чинна.");String e=party(a,c);validate(terms(id,expected),c);
        db.execute("MERGE INTO vc_accept KEY(contract,rev,estate) VALUES(?,?,?,?,?,'AGREED')",id,expected,e,a.id(),fingerprint(e));event(id,a.id(),"AGREE",e+" редакція "+expected);return null;
    });}
    public boolean sign(Actor a,long id,int expected){return db.transaction(()->{
        var c=get(id);current(c,expected);require(number(c,"active_rev")!=expected,"Редакція вже підписана.");String e=party(a,c);approved(c,expected);
        var t=terms(id,expected);validate(t,c);
        require(s.contract(string(c,"child"))==null,"Існує класичний договір; спершу завершіть його за згодою сторін.");
        String oldParent=s.parent(string(c,"child"));require(oldParent==null || oldParent.equals(string(c,"parent")),"Поточний сюзерен змінився; потрібне його погоджене звільнення.");
        s.validateLink(s.estate(string(c,"child")),s.estate(string(c,"parent")));
        db.execute("UPDATE vc_accept SET phase='SIGNED' WHERE contract=? AND rev=? AND estate=?",id,expected,e);event(id,a.id(),"SIGN",e+" редакція "+expected);
        if(number(db.one("SELECT COUNT(*) AS n FROM vc_accept WHERE contract=? AND rev=? AND phase='SIGNED'",id,expected),"n")<2)return false;
        require(active(string(c,"child"))==null || number(active(string(c,"child")),"id")==id,"Васал уже має інший договір.");
        if(number(c,"active_rev")>0){accrue(c);caughtUp(get(id));} // Final bill for the old schedule before replacing it.
        long ends=t.n("days")==0?0:Math.addExact(s.now(),Math.multiplyExact(t.n("days"),DAY));
        if(number(c,"active_rev")>0){var previous=terms(id,(int)number(c,"active_rev"));
            if(previous.n("days")==t.n("days"))ends=number(c,"ends");
            require(t.n("extend")==0 || previous.yes("renew") && ends>0,"Продовження можливе лише для строкового договору з дозволом продовження.");
            ends=ends==0?0:Math.addExact(ends,t.n("extend")*DAY);
        }else require(t.n("extend")==0,"Продовження застосовується лише до чинного договору.");
        db.execute("UPDATE vc_contract SET active_rev=?,status='ACTIVE',starts=?,ends=?,next_due=?,sub_due=? WHERE id=?",expected,s.now(),ends,t.firstDue(s.now()),s.now()+t.n("subperiod")*DAY,id);
        db.execute("UPDATE vc_contract SET exit_yes=NULL WHERE id=?",id);
        db.execute("UPDATE vc_revision SET expires_at=?,first_due=? WHERE contract=? AND rev=?",ends,t.firstDue(s.now()),id,expected);
        db.execute("UPDATE vc_revision SET child_name=?,parent_name=?,child_sign=?,parent_sign=?,signed_at=? WHERE contract=? AND rev=?",estateNames.apply(s.estate(string(c,"child"))),estateNames.apply(s.estate(string(c,"parent"))),s.estate(string(c,"child")).lord(),s.estate(string(c,"parent")).lord(),s.now(),id,expected);
        db.execute("UPDATE vc_revision SET child_sign_name=?,parent_sign_name=? WHERE contract=? AND rev=?",names.apply(s.estate(string(c,"child")).lord()),names.apply(s.estate(string(c,"parent")).lord()),id,expected);
        if(number(c,"active_rev")==0)autonomy(string(c,"parent"),"vassals");
        db.execute("MERGE INTO ties KEY(child) VALUES(?,?,NULL)",string(c,"child"),string(c,"parent"));
        if(number(c,"active_rev")==0 && t.money("aid")>0){s.restore("e:"+string(c,"parent"),"e:"+string(c,"child"),t.get("subcode"),t.money("aid"));event(id,"система","AID",format(t.money("aid"))+" "+t.get("subcode"));}
        event(id,"система","ACTIVE","Редакція "+expected);changed.run();return true;
    });}
    void validate(ContractTerms t,Map<String,Object> c)throws SQLException{
        t.validate();long checkedAt=s.now();require(t.firstDue(checkedAt)>=checkedAt,"Дата першого платежу вже минула. Узгодьте нову дату або відносний строк.");if(t.money("amount")+t.money("fine")+t.money("buyout")>0){s.currency(t.get("code"));if(s.market!=null)s.market.tribute(string(c,"parent"),t.get("code"));}
        if(t.money("subsidy")+t.money("aid")>0){s.currency(t.get("subcode"));if(s.market!=null)s.market.tribute(string(c,"child"),t.get("subcode"));}
    }
    public void legacyChange(String child)throws SQLException{require(active(child)==null,"Цей васалітет змінюється через конструктор /t treaty; чинні умови не можна обійти старою командою.");}
    public void autonomy(String child,String action)throws SQLException{
        var c=active(child);if(c==null)return;var t=terms(number(c,"id"),(int)number(c,"active_rev"));String mode=t.get(action);
        require(!"DENY".equals(mode),"Договір забороняє цю дію.");if("CONSENT".equals(mode))require(db.execute("DELETE FROM vc_permission WHERE child=? AND action=? AND rev=?",child,action,number(c,"active_rev"))==1,"Потрібне одноразове погодження сюзерена: /t treaty permit <договір> <право>.");
    }
    public void permit(Actor a,long id,String action){db.transaction(()->{var c=get(id);ruler(a,string(c,"parent"));require(active(string(c,"child"))!=null && Set.of("alliance","diplomacy","vassals","war").contains(action),"Немає чинного договору або невідоме право.");db.execute("MERGE INTO vc_permission KEY(child,action) VALUES(?,?,?)",string(c,"child"),action,number(c,"active_rev"));event(id,a.id(),"PERMIT",action);return null;});}
    void caughtUp(Map<String,Object> c){long cutoff=number(c,"ends")==0?s.now():Math.min(s.now(),number(c,"ends"));if(number(c,"exit_at")>0)cutoff=Math.min(cutoff,number(c,"exit_at"));require(number(c,"next_due")>cutoff && number(c,"sub_due")>cutoff,"Триває облік пропущених періодів. Зачекайте наступної синхронізації.");}
    void owe(long id,int rev,String source,String target,String asset,long amount,long due,boolean penalty)throws SQLException{if(amount>0)db.execute("INSERT INTO vc_obligation(contract,rev,source,target,asset,amount,due,penalty) VALUES(?,?,?,?,?,?,?,?)",id,rev,source,target,asset,amount,due,penalty);}
    void accrue(Map<String,Object> c)throws SQLException{
        long id=number(c,"id"),end=number(c,"ends"),cutoff=end==0?s.now():Math.min(end,s.now());if(number(c,"exit_at")>0)cutoff=Math.min(cutoff,number(c,"exit_at"));
        int rev=(int)number(c,"active_rev");var t=terms(id,rev);String child=string(c,"child"),parent=string(c,"parent");
        for(boolean sub:List.of(false,true)){
            String field=sub?"sub_due":"next_due",source=sub?parent:child,target=sub?child:parent;long due=number(c,field),period=t.n(sub?"subperiod":"period")*DAY;
            int count=0;while(due<=cutoff && count++<64){
                owe(id,rev,source,target,"coin:"+t.get(sub?"subcode":"code"),t.money(sub?"subsidy":"amount"),due,false);
                for(var item:t.items(sub?"provisions":"resources").entrySet())owe(id,rev,source,target,"item:"+item.getKey(),item.getValue(),due,false);
                due=Math.addExact(due,period);
            }
            db.execute("UPDATE vc_contract SET "+field+"=? WHERE id=?",due,id);
        }
    }
    public void tick(){db.transaction(()->{
        for(var c:db.query("SELECT * FROM vc_contract WHERE active_rev>0 AND status IN('ACTIVE','NOTICE')")){
            long id=number(c,"id");if(!s.estate(string(c,"child")).active() || !s.estate(string(c,"parent")).active()){close(c,"ARCHIVED");continue;}
            accrue(c);
        }
        for(var o:db.query("SELECT * FROM vc_obligation WHERE paid<amount AND asset LIKE 'coin:%' ORDER BY due,id")){
            long n=number(o,"amount")-number(o,"paid");String source=string(o,"source"),target=string(o,"target"),code=string(o,"asset").substring(5);
            if(s.balance("e:"+source,code)>=n){s.restore("e:"+source,"e:"+target,code,n);db.execute("UPDATE vc_obligation SET paid=amount WHERE id=?",number(o,"id"));event(number(o,"contract"),"система","PAY",source+" → "+target+": "+format(n)+" "+code);}
        }
        for(var o:db.query("SELECT * FROM vc_obligation WHERE paid<amount AND late=FALSE AND penalty=FALSE")){
            var t=terms(number(o,"contract"),(int)number(o,"rev"));if(s.now()>number(o,"due")+t.n("grace")*DAY){
                db.execute("UPDATE vc_obligation SET late=TRUE WHERE id=?",number(o,"id"));
                // One fixed fine for the entire source/due period, not one per item.
                if(db.one("SELECT id FROM vc_obligation WHERE contract=? AND source=? AND due=? AND penalty=TRUE",number(o,"contract"),string(o,"source"),number(o,"due"))==null)
                    owe(number(o,"contract"),(int)number(o,"rev"),string(o,"source"),string(o,"target"),"coin:"+t.get("code"),t.money("fine"),number(o,"due"),true);
                event(number(o,"contract"),"система","OVERDUE",string(o,"source")+": зобов’язання №"+number(o,"id"));
            }
        }
        for(var c:db.query("SELECT * FROM vc_contract WHERE active_rev>0 AND status IN('ACTIVE','NOTICE')")){
            long id=number(c,"id");var t=terms(id,(int)number(c,"active_rev"));
            boolean end=number(c,"ends")>0 && s.now()>=number(c,"ends"),exit=number(c,"exit_at")>0 && s.now()>=number(c,"exit_at");
            // Do not discard unbilled downtime beyond the per-tick batch.
            long cutoff=end?number(c,"ends"):exit?number(c,"exit_at"):s.now();
            if((end||exit) && number(c,"next_due")>cutoff && number(c,"sub_due")>cutoff){close(c,end?"EXPIRED":"ENDED");continue;}
            for(String source:List.of(string(c,"child"),string(c,"parent"))){long missed=number(db.one("SELECT COUNT(DISTINCT due) AS n FROM vc_obligation WHERE contract=? AND source=? AND late=TRUE AND penalty=FALSE",id,source),"n");if(number(c,"next_due")>cutoff && number(c,"sub_due")>cutoff && missed>t.n("misses") && t.get("breach").equals("TERMINATE")){close(c,"BREACHED");break;}}
        }
        return null;
    });}
    void close(Map<String,Object> c,String status)throws SQLException{db.execute("UPDATE vc_contract SET status=? WHERE id=?",status,number(c,"id"));db.execute("DELETE FROM ties WHERE child=? AND parent=? AND contract IS NULL",string(c,"child"),string(c,"parent"));event(number(c,"id"),"система",status,"Борги й історія збережені.");changed.run();}
    public void exit(Actor a,long id,boolean unilateral){db.transaction(()->{var c=get(id);String side=party(a,c);require(Set.of("ACTIVE","NOTICE").contains(string(c,"status")),"Договір не чинний.");var t=terms(id,(int)number(c,"active_rev"));
        if(unilateral){require(t.yes("unilateral") && number(c,"exit_at")==0,"Односторонній вихід заборонено або вже заявлено.");String other=side.equals(string(c,"child"))?string(c,"parent"):string(c,"child");if(t.money("buyout")>0)s.restore("e:"+side,"e:"+other,t.get("code"),t.money("buyout"));long at=s.now()+t.n("notice")*DAY;db.execute("UPDATE vc_contract SET status='NOTICE',exit_at=?,exit_party=? WHERE id=?",at,side,id);event(id,a.id(),"NOTICE",side+"; вихід="+at+"; викуп="+t.get("buyout"));}
        else {String agreed=string(c,"exit_yes");if(agreed!=null && !agreed.equals(side)){accrue(c);caughtUp(get(id));close(c,"ENDED");}else db.execute("UPDATE vc_contract SET exit_yes=? WHERE id=?",side,id);event(id,a.id(),"EXIT_AGREE",side);}
        return null;
    });}
    public List<Map<String,Object>> debts(long id)throws SQLException{return db.query("SELECT * FROM vc_obligation WHERE contract=? AND paid<amount ORDER BY due,id",id);}
    public List<Map<String,Object>> history(long id,int page)throws SQLException{require(page>=0 && page<100000,"Неправильна сторінка.");return db.query("SELECT * FROM vc_history WHERE contract=? ORDER BY seq DESC LIMIT 30 OFFSET ?",id,page*30);}
    /** Inventory changes use the existing durable Commerce journal and its admin recovery flow. */
    public String supply(Actor a,long obligation,long n,CommerceService commerce,CommerceService.InventoryChange change){return db.transaction(()->{
        var o=db.one("SELECT * FROM vc_obligation WHERE id=?",obligation);require(o!=null && string(o,"asset").startsWith("item:"),"Ресурсне зобов’язання не знайдено.");ruler(a,string(o,"source"));require(n>0 && n<=number(o,"amount")-number(o,"paid"),"Кількість перевищує борг.");require(db.one("SELECT i.op FROM vc_item i JOIN item_ops o ON o.id=i.op WHERE i.obligation=? AND o.status='PREPARED'",obligation)==null,"Поставка вже готується.");require(change.person().equals(a.id()),"Чужий інвентар.");
        String op=commerce.intent(a,"VC_IN",null,n,List.of(change));db.execute("INSERT INTO vc_item VALUES(?,?,?,?,?,FALSE)",op,obligation,string(o,"target"),string(o,"asset").substring(5),n);return op;
    });}
    public String collect(Actor a,String estate,String material,long n,CommerceService commerce,CommerceService.InventoryChange change){return db.transaction(()->{
        ruler(a,estate);require(change.person().equals(a.id()) && n>0,"Неправильна передача.");var row=db.one("SELECT quantity FROM vc_goods WHERE estate=? AND material=?",estate,material);require(row!=null && number(row,"quantity")>=n,"На складі недостатньо ресурсів.");db.execute("UPDATE vc_goods SET quantity=quantity-? WHERE estate=? AND material=?",n,estate,material);
        String op=commerce.intent(a,"VC_OUT",null,n,List.of(change));db.execute("INSERT INTO vc_item VALUES(?,NULL,?,?,?,TRUE)",op,estate,material,n);return op;
    });}
    static void finishItems(Database db,String op,boolean applied)throws SQLException{
        var i=db.one("SELECT * FROM vc_item WHERE op=?",op);require(i!=null,"Немає запису передачі договору.");long n=number(i,"quantity");boolean withdrawal=bool(i,"withdrawal");
        if(!withdrawal && applied){var o=db.one("SELECT contract,source,target FROM vc_obligation WHERE id=?",number(i,"obligation"));db.execute("UPDATE vc_obligation SET paid=paid+? WHERE id=?",n,number(i,"obligation"));db.execute("INSERT INTO vc_history(contract,at_time,actor,event,detail) SELECT ?,created,actor,'SUPPLY',? FROM item_ops WHERE id=?",number(o,"contract"),string(o,"source")+" → "+string(o,"target")+": "+n+" "+string(i,"material"),op);}
        if(!withdrawal && applied || withdrawal && !applied){String estate=string(i,"estate"),material=string(i,"material");var g=db.one("SELECT quantity FROM vc_goods WHERE estate=? AND material=?",estate,material);db.execute("MERGE INTO vc_goods KEY(estate,material) VALUES(?,?,?)",estate,material,Math.addExact(g==null?0:number(g,"quantity"),n));}
    }
}
